const LanguageContext = createContext(null);

export function LanguageProvider({ children }) {
  const [language, setLanguage] = useState(() => localStorage.getItem("givera-language") || "en");
  useEffect(() => {
    localStorage.setItem("givera-language", language);
    document.documentElement.lang = language === "my" ? "my" : "en";
  }, [language]);
  const value = useMemo(() => {
    const locale = language === "my" ? "my-MM" : "en-US";
    return {
      language,
      setLanguage,
      t: (key) => messages[language]?.[key] || messages.en[key] || key,
      formatNumber: (number) => new Intl.NumberFormat(locale).format(Number(number || 0)),
      formatKyat: (number) => `${new Intl.NumberFormat(locale, { maximumFractionDigits: 2 }).format(Number(number || 0))} ${language === "my" ? "ကျပ်" : "Ks"}`,
      formatDate: (date, options = { year: "numeric", month: "short", day: "numeric" }) => date ? new Intl.DateTimeFormat(locale, options).format(new Date(date)) : "—",
    };
  }, [language]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

// This module intentionally exports the provider and its paired hook.
// eslint-disable-next-line react-refresh/only-export-components
export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) throw new Error("useLanguage must be used inside LanguageProvider");
  return context;
}
